function build(api) {
  api.name('小鸣禽');
  const C_BLUE = 0x87ceeb, C_WHITE = 0xf0f8ff, C_ORANGE = 0xff8c00, C_BLACK = 0x1a1a1a, C_BROWN = 0x5c4033;

  api.group('branch', '树枝');
    api.cyl({r: 0.15, h: 4, pos: [0, 1.5, 0], along: '+X', color: C_BROWN});
    api.fork({from: [1.2, 1.5, 0], to: [[1.8, 2.1, 0.4]], r: 0.08, color: C_BROWN});
  api.endGroup();

  for (let side = 0; side < 2; side++) {
    let sx = side === 0 ? 1 : -1;
    api.group(side === 0 ? 'leftLeg' : 'rightLeg', side === 0 ? '左腿' : '右腿');
      api.pivot([sx * 0.3, 2.2, 0], 'body');
      api.chain({waypoints: [[sx * 0.3, 2.2, 0], [sx * 0.3, 1.7, 0.1], [sx * 0.3, 1.5, 0]], rStart: 0.08, rEnd: 0.05, color: C_ORANGE});
      api.cone({r: 0.04, h: 0.4, pos: [sx * 0.3, 1.45, 0.2], along: '+Z', color: C_ORANGE});
      api.cone({r: 0.04, h: 0.35, pos: [sx * 0.15, 1.45, 0.15], along: '+Z-X', color: C_ORANGE});
      api.cone({r: 0.04, h: 0.35, pos: [sx * 0.45, 1.45, 0.15], along: '+Z+X', color: C_ORANGE});
      api.cone({r: 0.04, h: 0.3, pos: [sx * 0.3, 1.45, -0.15], along: '-Z', color: C_ORANGE});
    api.endGroup();
  }

  api.group('body', '躯干');
    api.pivot([0, 2.5, 0], 'branch');
    api.sphere({r: 0.8, pos: [0, 2.5, 0.3], color: C_WHITE});
    api.sphere({r: 0.75, pos: [0, 2.5, -0.2], color: C_BLUE});
    api.box({w: 0.8, h: 0.6, d: 0.6, pos: [0, 2.0, 0.1], color: C_WHITE});
    api.box({w: 0.4, h: 0.3, d: 0.3, pos: [0, 2.2, -0.8], color: C_BLUE});
  api.endGroup();

  for (let side = 0; side < 2; side++) {
    let sx = side === 0 ? 1 : -1;
    api.group(side === 0 ? 'leftWing' : 'rightWing', side === 0 ? '左翼' : '右翼');
      api.pivot([sx * 0.7, 2.5, 0], 'body');
      api.box({w: 0.15, h: 0.6, d: 1.2, pos: [sx * 0.8, 2.5, -0.2], color: C_BLUE});
      api.box({w: 0.1, h: 0.4, d: 0.8, pos: [sx * 0.85, 2.3, -0.9], color: C_WHITE});
    api.endGroup();
  }

  api.group('tail', '尾羽');
    api.pivot([0, 2.2, -0.8], 'body');
    api.box({w: 0.1, h: 0.1, d: 1.5, pos: [0.15, 2.1, -1.8], color: C_BLUE});
    api.box({w: 0.1, h: 0.1, d: 1.5, pos: [-0.15, 2.1, -1.8], color: C_BLUE});
    api.box({w: 0.1, h: 0.1, d: 1.2, pos: [0, 2.15, -1.6], color: C_BLUE});
  api.endGroup();

  api.group('head', '头部');
    api.pivot([0, 3.2, 0.3], 'body');
    api.sphere({r: 0.7, pos: [0, 3.4, 0.5], color: C_BLUE});
    api.sphere({r: 0.6, pos: [0, 3.3, 0.7], color: C_WHITE});
    api.cone({r: 0.15, h: 0.5, pos: [0, 3.3, 1.2], along: '+Z', color: C_ORANGE});
    api.poly({r: 0.15, pos: [0.35, 3.5, 0.9], color: C_BLACK});
    api.poly({r: 0.15, pos: [-0.35, 3.5, 0.9], color: C_BLACK});
    api.cone({r: 0.2, h: 0.5, pos: [0, 4.0, 0.4], along: '+Y-Z', color: C_BLUE});
  api.endGroup();
}
